package com.littlemakers.village.nativeapp;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
/** Three original learning games using native controls over lit, animated GLES meshes. */
public final class QuestActivity extends Activity {
 private VisualPlayMenu visualMenu;private ThemeManager theme;private SoundEngine sound;private GameDatabase db;private PlayerWallet wallet;private LearningQuest quest;private NativeStageSurface stage;private LinearLayout root,body,controls;private TextView prompt,message,program,balanceLine;private final Handler handler=new Handler(Looper.getMainLooper());private android.animation.ValueAnimator walking;private float actorX,actorY;private boolean running,active;private int runAt;private String route="";private long resetGeneration;
 private android.content.SharedPreferences prefs(){return getSharedPreferences("learning_quests",0);}
 private int dp(int n){return theme.dp(n);}private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextColor(theme.text);v.setTypeface(theme.font(true));v.setTextSize(size);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(theme.text);b.setTypeface(theme.font(true));b.setTextSize(17);b.setMinHeight(dp(64));b.setBackground(theme.panel(true));b.setOnClickListener(v->{sound.tap();v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);action.run();});GameUi.control(b,theme);return b;}
 private boolean reduced(){return getSharedPreferences("family",0).getBoolean("reduce_motion",false)||android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;}
 @Override public void onCreate(Bundle b){super.onCreate(b);db=GameDatabase.create(this);wallet=new PlayerWallet(db);sound=new SoundEngine(this);resetGeneration=getSharedPreferences("family",0).getLong("quest_reset_generation",0);active=true;int mode=b==null?getIntent().getIntExtra("mode",-1):b.getInt("mode",-1);if(mode>=0&&mode<3){if(b==null&&getIntent().hasExtra("quest_stage")){int target=Math.max(0,Math.min(23,getIntent().getIntExtra("quest_stage",0)));prefs().edit().putInt("level"+mode,target).putBoolean("won"+mode,false).putInt("weight"+mode,0).putString("commands"+mode,"").apply();}load(mode);}else menu();if(Build.VERSION.SDK_INT>=33)Back.register(this);}
 static final class Back{static void register(QuestActivity a){a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,a::back);}}
 private void base(String title){if(visualMenu!=null){visualMenu.pause();visualMenu=null;}stop();if(stage!=null){stage.onPause();stage=null;}theme=new ThemeManager(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(theme.background);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();getWindow().getDecorView().setSystemUiVisibility(theme.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);LinearLayout top=new LinearLayout(this);Button home=button("‹ Games",()->{save();menu();});home.setContentDescription("Back to learning quest selection");top.addView(home,new LinearLayout.LayoutParams(dp(110),dp(64)));top.addView(text(title,23),new LinearLayout.LayoutParams(0,-2,1));root.addView(top);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(8),dp(12),dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 private void menu(){quest=null;base("Pick an adventure");body.addView(GameUi.card(this,theme,"Learning trail","Kindergarten–Class 10 · 264 starter activities",22,0xffa5b9da,true,false,()->startActivity(new Intent(this,SchoolTrailActivity.class))));String[]names=new String[3+ExplorerCatalog.NAMES.length];System.arraycopy(LearningQuest.NAMES,0,names,0,3);System.arraycopy(ExplorerCatalog.NAMES,0,names,3,ExplorerCatalog.NAMES.length);String[]labels={"Numbers","Balance","Robot","Discover","Letters","Islands","Friends","Shapes","Build"};int[]icons={100,101,102,103,104,105,106,107,108};visualMenu=new VisualPlayMenu(this,theme,names,icons,item->{sound.tap();if(item<3)load(item);else startActivity(new Intent(this,StudioActivity.class).putExtra("mode",item-3));});body.addView(visualMenu,new LinearLayout.LayoutParams(-1,-2));body.addView(text("Tap a toy to play",16));body.addView(button("More puzzles",()->startActivity(new Intent(this,MainActivity.class).putExtra("destination","playroom").putExtra("adventure_return",true))));body.addView(button("⌂ Island",this::finish));}
 private void load(int mode){int n=Math.max(0,Math.min(23,prefs().getInt("level"+mode,0)));quest=new LearningQuest(mode,n,prefs().getInt("tier",0));quest.streak=Math.max(0,Math.min(1,prefs().getInt("streak",0)));quest.weight=Math.max(0,Math.min(12,prefs().getInt("weight"+mode,0)));String saved=prefs().getString("commands"+mode,"");for(char c:saved.toCharArray())quest.append(c);if(prefs().getBoolean("won"+mode,false)){if(mode==2){for(char c:quest.commands.toString().toCharArray())quest.step(c);}quest.won=true;wallet.creativeCompletion(quest.rewardKey());}render();}
 private void save(){if(quest==null)return;prefs().edit().putInt("level"+quest.mode,quest.stage).putInt("tier",quest.tier).putInt("streak",quest.streak).putInt("weight"+quest.mode,quest.weight).putString("commands"+quest.mode,quest.commands.toString()).putBoolean("won"+quest.mode,quest.won).apply();}
 private void render(){actorX=quest.x;actorY=quest.y;base(LearningQuest.NAMES[quest.mode]);balanceLine=text("Stage "+(quest.stage+1)+" / 24 · "+wallet.stars()+" stars",16);body.addView(balanceLine);prompt=text("",22);body.addView(prompt);FrameLayout scene=new FrameLayout(this);body.addView(scene,new LinearLayout.LayoutParams(-1,dp(300)));if(((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion>=0x20000){stage=new NativeStageSurface(this,theme.dark,()->{if(stage!=null){stage.onPause();scene.removeView(stage);stage=null;scene.addView(text("The learning controls below are ready.",18));}});scene.addView(stage,new FrameLayout.LayoutParams(-1,-1));}message=text(quest.won?"Well explored! Your first-clear reward is saved.":"",18);body.addView(message);controls=new LinearLayout(this);controls.setOrientation(1);body.addView(controls);refreshControls();draw();}
 private void row(String[] labels,Runnable[]actions){LinearLayout row=new LinearLayout(this);for(int i=0;i<labels.length;i++)row.addView(button(labels[i],actions[i]),new LinearLayout.LayoutParams(0,-2,1));controls.addView(row);}
 private void refreshControls(){controls.removeAllViews();if(quest.won){controls.addView(button(quest.stage==23?"Replay this game":"Next discovery",()->{int mode=quest.mode,next=(quest.stage+1)%24,tier=quest.tier,streak=quest.streak;quest=new LearningQuest(mode,next,tier);quest.streak=streak;save();render();}));return;}if(quest.mode==0){int[]values=quest.choices();String[]labels=new String[3];Runnable[]a=new Runnable[3];for(int i=0;i<3;i++){final int value=values[i];labels[i]=""+value;a[i]=()->answer(value);}row(labels,a);controls.addView(button("Hear the question",()->speak(quest.question())));}else if(quest.mode==1){row(new String[]{"− Remove","+ Add"},new Runnable[]{()->weight(-1),()->weight(1)});controls.addView(button("Test the balance",()->{if(quest.balance())win();else{message.setText(quest.known()+" + "+quest.weight+" is "+(quest.known()+quest.weight<quest.total()?"lighter":"heavier")+" than "+quest.total()+". Try another weight.");sound.note(0);}save();draw();}));}else{program=text("",18);controls.addView(program);row(new String[]{"↶ Left","↑ Forward","↷ Right"},new Runnable[]{()->command('L'),()->command('F'),()->command('R')});row(new String[]{"Undo","Clear"},new Runnable[]{()->{if(!running){quest.undo();changed();}},()->{if(!running){quest.commands.setLength(0);quest.rewind();changed();}}});controls.addView(button("Run my robot",this::run));controls.addView(text("Robot starts facing right →. Reach the flower at bottom right. Rocks block the way. Up to 32 commands.",16));changed();}controls.addView(button("Show a helpful clue",this::hint));}
 private android.speech.tts.TextToSpeech voice;private boolean voiceReady;private String speech;
 private void speak(String s){speech=s;if(voice==null)voice=new android.speech.tts.TextToSpeech(this,status->{if(status==android.speech.tts.TextToSpeech.SUCCESS){voice.setLanguage(java.util.Locale.ENGLISH);boolean offline=false;for(android.speech.tts.Voice v:voice.getVoices()==null?java.util.Collections.<android.speech.tts.Voice>emptySet():voice.getVoices()){if(!v.isNetworkConnectionRequired()&&v.getLocale().getLanguage().equals("en")){voice.setVoice(v);offline=true;break;}}voiceReady=offline;if(offline&&active)voice.speak(speech,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"quest");else if(!offline){message.setText("An offline English voice is unavailable. Read the question above.");voice.shutdown();voice=null;}}});else if(voiceReady)voice.speak(s,android.speech.tts.TextToSpeech.QUEUE_FLUSH,null,"quest");}
 private void answer(int n){int old=quest.tier;if(quest.choose(n))win();else{message.setText(old!=quest.tier?"Let's count a smaller collection together.":"Try counting each seed. You can take your time.");sound.note(0);save();refreshControls();draw();}}
 private void weight(int d){quest.adjust(d);message.setText("Mystery weight: "+quest.weight+" · Left total: "+(quest.known()+quest.weight));save();draw();}
 private void hint(){if(running)return;if(quest.mode==0)message.setText(quest.tier==0?"Touch each seed with your finger and count slowly.":quest.subtract()?"Start with "+quest.a()+". Take away "+quest.b()+".":"Start with "+quest.a()+". Count on "+quest.b()+" more.");else if(quest.mode==1)message.setText("The right side has "+quest.total()+". The left already has "+quest.known()+". How many more?");else message.setText("One safe path goes across the top row, then down the right edge. Start with three Forward commands.");}
 private void command(char c){if(!running){if(!quest.append(c))message.setText("Your program can hold 32 commands. Undo a step to make room.");changed();}}
 private void changed(){if(!running){actorX=quest.x;actorY=quest.y;}if(program!=null)program.setText("Your program: "+(quest.commands.length()==0?"empty":quest.commands.toString().replace("F"," → ").replace("L"," ↶ ").replace("R"," ↷ ")));save();draw();}
 private void run(){if(running||quest.won)return;if(quest.commands.length()==0){message.setText("Add a command first.");return;}quest.rewind();actorX=actorY=0;route=quest.commands.toString();runAt=0;running=true;message.setText("Watch your robot follow your commands.");handler.post(tick);}
 private final Runnable tick=new Runnable(){public void run(){if(!active||!running)return;if(runAt==route.length()){running=false;if(quest.finishRoute())win();else message.setText("Your robot stopped here. Edit your program and explore another route.");draw();return;}if(!quest.step(route.charAt(runAt++))){running=false;message.setText("A rock or edge is in the way. Edit your route and try again.");draw();return;}sound.note(runAt%3);animateRobot();handler.postDelayed(this,reduced()?300:550);}};
 private void win(){wallet.creativeCompletion(quest.rewardKey());balanceLine.setText("Stage "+(quest.stage+1)+" / 24 · "+wallet.stars()+" stars");save();sound.win();message.setText(quest.mode==0?"The seeds glow! You helped the guardian's garden.":quest.mode==1?"Both sides are equal! You found the mystery weight.":"Your robot reached the flower! Your program worked.");refreshControls();draw();}
 private void animateRobot(){if(walking!=null)walking.cancel();float fromX=actorX,fromY=actorY;if(reduced()){actorX=quest.x;actorY=quest.y;draw();return;}walking=android.animation.ValueAnimator.ofFloat(0,1);walking.setDuration(350);walking.setInterpolator(new android.view.animation.AccelerateDecelerateInterpolator());final float targetX=quest.x,targetY=quest.y;walking.addUpdateListener(a->{float t=(Float)a.getAnimatedValue();actorX=fromX+(targetX-fromX)*t;actorY=fromY+(targetY-fromY)*t;draw();});walking.start();}
 private void stop(){handler.removeCallbacksAndMessages(null);running=false;if(walking!=null){walking.cancel();walking=null;}if(quest!=null){actorX=quest.x;actorY=quest.y;}}
 private void draw(){if(quest==null)return;List<SceneFrame.Node>nodes=new ArrayList<>();if(quest.mode==0){prompt.setText(quest.won?"A growing garden":quest.question());for(int row=0;row<4;row++)nodes.add(SceneFrame.panel(35,90+row*69,435,116+row*69,0xb79770));nodes.add(SceneFrame.model(540,90,65,StoryModels.TREE,0x69a87b,true));nodes.add(new SceneFrame.Node(SceneFrame.CHARACTER,530,236,88,88,35,wallet.skinColor(),wallet.equipped("accessory").equals("hat")?1:0,true));int count=quest.answer();for(int i=0;i<count;i++)nodes.add(SceneFrame.model(70+(i%5)*78,74+(i/5)*69,45,quest.won?StoryModels.FLOWER:StoryModels.SEEDLING,0x75b78b,true));}else if(quest.mode==1){prompt.setText(quest.known()+" + ? = "+quest.total()+" · Your weight: "+quest.weight);nodes.add(new SceneFrame.Node(6,320,174,296,136,-40,theme.dark?0x344353:0xf2ead8,0,false));int tilt=quest.won?0:Integer.compare(quest.known()+quest.weight,quest.total())*24;nodes.add(SceneFrame.shape(320,254,34,1,0xd9b17c));nodes.add(new SceneFrame.Node(6,320,140,205,6,0,0xd9b17c,-tilt*36,false));nodes.add(new SceneFrame.Node(6,320,188,4,48,6,0xd9b17c,0,false));nodes.add(new SceneFrame.Node(6,162,173+tilt,2,32,5,0xa4aeb8,0,false));nodes.add(new SceneFrame.Node(6,478,173-tilt,2,32,5,0xa4aeb8,0,false));nodes.add(SceneFrame.panel(60,206+tilt,265,229+tilt,0x8fb9d0));nodes.add(SceneFrame.panel(375,206-tilt,580,229-tilt,0x8fb9d0));for(int i=0;i<quest.known()+quest.weight;i++)nodes.add(SceneFrame.shape(82+i%5*36,183+tilt-i/5*32,13,0,0x83bd9a));for(int i=0;i<quest.total();i++)nodes.add(SceneFrame.shape(398+i%5*36,183-tilt-i/5*32,13,0,0xe6bd71));}else{nodes.add(new SceneFrame.Node(6,315,157,205,157,-40,theme.dark?0x263747:0xc8b38f,0,false));prompt.setText(quest.won?"A helpful little programmer!":"Face "+new String[]{"right →","down ↓","left ←","up ↑"}[quest.heading]+" · reach the flower");for(int y=0;y<4;y++)for(int x=0;x<4;x++){nodes.add(SceneFrame.panel(125+x*98,12+y*72,215+x*98,77+y*72,theme.dark?0x344a58:0xd1e3d7));if(quest.blocked(x,y))nodes.add(SceneFrame.shape(170+x*98,45+y*72,22,2,0x8593a0));}nodes.add(SceneFrame.model(464,261,28,StoryModels.FLOWER,0xf0bf6a,true));nodes.add(new SceneFrame.Node(SceneFrame.CHARACTER,170+actorX*98,45+actorY*72,34,34,40,wallet.skinColor(),0,true));message.setContentDescription(message.getText()+" Robot at row "+(quest.y+1)+", column "+(quest.x+1)+", facing "+new String[]{"right","down","left","up"}[quest.heading]);}if(stage!=null)stage.submit(new SceneFrame(nodes,theme.background,320,"welcome",quest.won));}
 private void back(){save();if(quest!=null)menu();else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onPause(){active=false;if(visualMenu!=null)visualMenu.pause();stop();save();if(stage!=null)stage.onPause();if(voice!=null)voice.stop();sound.stop();super.onPause();}
 @Override protected void onResume(){super.onResume();active=true;long generation=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(generation!=resetGeneration){resetGeneration=generation;quest=null;menu();}else if(visualMenu!=null&&(new ThemeManager(this).dark!=theme.dark||visualMenu.reducedMotion()!=reduced()))menu();else if(visualMenu!=null)visualMenu.resume();else if(stage!=null)stage.onResume();}
 @Override protected void onSaveInstanceState(Bundle b){save();b.putInt("mode",quest==null?-1:quest.mode);super.onSaveInstanceState(b);}
 @Override protected void onDestroy(){stop();if(voice!=null)voice.shutdown();sound.stop();db.close();super.onDestroy();}
}
